#include "../RundeUhr/IssParse.h"
#include <cassert>
#include <iostream>
int main(){assert(nextView(12,(1<<12)|(1<<13))==13);assert(nextView(13,(1<<12)|(1<<13))==12);time_t now=1794850218;JsonDocument d;deserializeJson(d,R"({"id":25544,"units":"kilometers","latitude":0,"longitude":0,"altitude":420,"velocity":27600,"timestamp":1794850218})");IssData i;assert(parseIss(d,i,now));assert(!issStale(i,now+90));assert(issStale(i,now+91));assert(issStale(i,now-1));auto l=issLook(i,0,0);assert(fabs(l.distance-420)<.001&&fabs(l.elevation-90)<.001);l=issLook(i,0,180);assert(l.elevation < -89.99);i.lon=10;l=issLook(i,0,0);assert(fabs(l.azimuth-90)<.001);i.lon=-10;l=issLook(i,0,0);assert(fabs(l.azimuth-270)<.001);
for(auto k:{"latitude","longitude","altitude","velocity","timestamp"}){JsonDocument bad;bad.set(d);bad[k]=nullptr;IssData target=i;assert(!parseIss(bad,target,now));assert(target.lon==i.lon);}
d["latitude"]=91;assert(!parseIss(d,i,now));d["latitude"]=0;d["timestamp"]=now-91;assert(!parseIss(d,i,now));d["timestamp"]=now+11;assert(!parseIss(d,i,now));d["timestamp"]=now;d["units"]="miles";assert(!parseIss(d,i,now));std::cout<<"PASS ISS validation, stale/future timestamps, missing fields, geometry overhead/antipode/east/west\n";}
